WITH flattened_attrs AS (SELECT id, plan, effective_from, tier_limits, tier_prices, discounts, ZIP_WITH(tier_prices, discounts, (p, d) -> ROUND(p * (1 - d), 2)) AS net_prices, ARRAY_MIN(tier_prices) AS lowest_price, TRANSFORM(tier_prices, (p, i) -> ROUND(p * tier_limits[i], 2)) AS tier_revenue_caps, SLICE(tier_limits, 1, 2) AS first_two_limits FROM price_tiers WHERE effective_from BETWEEN '2023-03-01' AND '2024-01-10') SELECT id, plan, lowest_price, AVG(lowest_price) OVER (PARTITION BY plan ORDER BY lowest_price, id ROWS BETWEEN 6 PRECEDING AND CURRENT ROW) AS lowest_price_avg_6, SUM(lowest_price) OVER w_part AS cumulative_lowest_price FROM flattened_attrs WINDOW w_part AS (PARTITION BY plan ORDER BY effective_from, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW);
